from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent
rows=[
('B01','先看火烧连营',5,'B01-火烧连营.png', '''Five seconds of real live-action historical war cinematography. Preserve the reference's uneven camp, wooded slope, dry ground, dusk light and distinct pockets of fire. Camera moves smoothly RIGHT about1meter from behind the near charred post, revealing the linked camps continuing deep into the valley. Only the existing few small soldiers run unevenly along the road away from fire, each with real footfalls and body weight. Burning canvas sags and smoke bends with wind. Flames attach to physical wood and cloth, not a flat wall. No new army, no marching formation, no glossy armor, no drone rise, no explosion. The wide shot's subject is the burning connected encampments. Only wind, nearby crackling wood, distant collapse and running footsteps. No words, no narrator, no music. Full frame16:9.'''),
('B02','两将穿过败营告急',6,'B02-两将穿行.png', '''Six seconds, one urgent live-action medium tracking shot. SAME two reference men already on foot in the smoky narrow lane, not riding. Camera retreats at their walking speed. Left foreground commander in red-brown scarf Feng Xi turns toward his companion while taking two real hurried steps and shouts ONCE in Mandarin: “御营败了，速去救驾！” Finish by4seconds. Only Feng Xi speaks. Right headwrapped Zhang Nan lowers the sleeve from his mouth, listens, then looks sharply forward past camera toward the blocked route. His mouth stays closed. Keep their feet outside frame; waist/shoulder weight and cloth respond naturally. Two blurred men in background cross once, no new crowd or spear formation. Ash falls, nearby singed canvas shifts; no heroic posing. Natural voices, rough breathing, boots, armor leather and fire. No other words, no narrator, NO music. No cuts or text,16:9.'''),
('B04','傅肜撑起身体拒降',8,'B04-傅肜断后.png', '''Eight-second single live-action medium shot of the SAME weary armored Fu Rong braced on the charred fence. His body and sword have real weight. An enemy voice from OFFSCREEN RIGHT says ONCE in Mandarin during0.2—1.2seconds: “降了，免死！” Fu Rong keeps his mouth closed while listening and looks to that right-side enemy. Then ONLY Fu Rong replies clearly: “吴狗！何有汉将军降者！” during1.8—5.8seconds. After finishing, he releases the left supporting hand, pushes off the post and takes ONE firm step toward screen right, bringing his sword slightly up. Do not swing or stage a duel. Enemy remains entirely outside the image, no shoulder inserted. The one background man retreats into smoke. Camera moves slightly right with Fu Rong's step, keep head and sword hand readable. Natural breath, voice, armor and timber fire, absolutely no music or other words. Real practical film set and textured skin, no game animation. Full frame16:9.''')]
plan=json.loads((R/'production-plan.json').read_text('utf-8'))
for id,title,dur,ref,prompt in rows:
 d=R/id;d.mkdir(exist_ok=True)
 if (d/'state.json').exists():continue
 refs=[str(R/'references'/ref)];assert Path(refs[0]).exists()
 (d/'prompt.txt').write_text(prompt+'\n','utf-8');(d/'references.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2),'utf-8')
 u=dict(id=id,title=title,duration=dur,edit_duration=dur,reference_paths=refs,depends_on=None,version='v2.2',prompt_sha256=hashlib.sha256((d/'prompt.txt').read_bytes()).hexdigest())
 if id not in [x['id'] for x in plan['units']]:plan['units'].append(u)
(R/'production-plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2),'utf-8')
